INSERT INTO model_sets (id, title, description, category_id, vacancy_id, question_ids, time_limit_minutes, total_marks, status)
VALUES ('027ac9ca-963f-49ce-9096-231591b45da4', 'CTET CDP Mock Set 2 (New)', 'Another comprehensive 25-questions mock model MCQ set covering CTET CDP syllabus.', @cat_id, @vac_id, '["50662fb9-9462-4a1a-b19c-293151fa4609", "4ef54e11-c1bb-4061-9845-8ce6a9033568", "db4d9648-d1a8-405b-ba8e-6645a74ac740", "ed6c5c54-f89a-406b-b009-1b2ddc0f9215", "360d6500-ca5d-4e2b-a988-79aab077c7f5", "9aa42237-0393-40ee-a6fe-54bf47eb77aa", "5cb32f68-5403-49f5-84f5-4435b1b89c8d", "493c24b8-55c5-4741-a673-47b2863f7c44", "0890de02-c932-4be9-98ff-1532dde45c7e", "ea46b3a7-42ed-4624-a7f0-088f8fca27a3", "01085758-8659-41a8-9dd0-74c471801390", "fc3310df-a6ce-42c2-8cdc-76491d70f034", "a6450918-5ea4-4a53-b220-d91d748e6386", "a6f83dff-4c52-43e3-93b0-b14342ef6410", "b3394659-174f-4346-812a-4260a5f4c735", "88cc9384-8256-4658-b63f-a3292c755344", "a2268a7a-bb1b-44be-acaa-94d0380c1954", "9d8177c9-55ed-4258-a826-d7cbe0cfd78e", "089f46df-83e8-4375-9f74-0effeb75f8e3", "8a7e61da-ae04-40a2-853b-8fa3b8d5e240", "f89feeac-5dd0-4687-8985-1484157fefd2", "e8ca9d8a-aeb0-49db-b069-21ee4f91e7ea", "6c320511-0875-42bf-8775-307fcb86ea52", "aa495da9-b39b-4d10-a5c2-fae70c9a578c", "1f05ec27-6a93-428d-b47b-ff5251604ae5"]', 30, 25.00, 'published');
